mapper.select:
        SELECT


--         级联表的字段
        ,assessment_paper.name as paperName
        ,assessment_paper.duration_minutes as paperDurationMinutes
        ,assessment_paper.total_score as paperTotalScore
        ,assessment_paper.status as paperStatus
        ,assessment_paper.is_deleted as paperIsDeleted
        ,student.name as studentName
        ,student.phone as studentPhone
        ,student.id_card_no as studentIdCardNo
        ,student.avatar_url as studentAvatarUrl
        ,student.email as studentEmail

        FROM assessment_record  a
        left JOIN assessment_paper assessment_paper ON a.paper_id = assessment_paper.id
        left JOIN student student ON a.student_id = student.id



                and a.id in

                #{item}



                and a.record_no like CONCAT('%',#{params.recordNo},'%')


                and (
                    a.student_id = #{params.studentId}
                )




                and exists (
                    select 1
                    from counseling_appointment ca
                    where ca.student_id   = a.student_id
                      and ca.counselor_id = #{params.counselorId}
                      and ca.status       = #{params.approvedStatus}
                )


                and (
                    a.paper_id = #{params.paperId}
                )


                  and a.total_score >= #{params.totalScoreStart}   


                  and a.total_score <= #{params.totalScoreEnd}   


                and a.total_score = #{params.totalScore}


                  and UNIX_TIMESTAMP(a.submitted_at) >= UNIX_TIMESTAMP(#{params.submittedAtStart}) 


                  and UNIX_TIMESTAMP(a.submitted_at) <= UNIX_TIMESTAMP(#{params.submittedAtEnd}) 




                and a.paper_id IS NOT NULL


                and assessment_paper.name like CONCAT('%',#{params.paperName},'%')


                  and assessment_paper.duration_minutes >= #{params.exampaperDateStart}   


                  and assessment_paper.duration_minutes <= #{params.exampaperDateEnd}   


                and assessment_paper.duration_minutes = #{params.paperDurationMinutes}


                  and assessment_paper.total_score >= #{params.exampaperMyscoreStart}   


                  and assessment_paper.total_score <= #{params.exampaperMyscoreEnd}   


                and assessment_paper.total_score = #{params.paperTotalScore}


                and assessment_paper.status = #{params.paperStatus}



                  and assessment_paper.is_deleted >= #{params.exampaperDeleteStart}   


                  and assessment_paper.is_deleted <= #{params.exampaperDeleteEnd}   


                and assessment_paper.is_deleted = #{params.paperIsDeleted}



                and a.student_id IS NOT NULL


                and student.name like CONCAT('%',#{params.studentName},'%')


                and student.phone like CONCAT('%',#{params.studentPhone},'%')


                and student.id_card_no like CONCAT('%',#{params.studentIdCardNo},'%')


                and student.email like CONCAT('%',#{params.studentEmail},'%')



        order by a.${params.orderBy} desc
